const CACHE='lumina-v6';const ASSETS=['./','./index.html','./style.css','./engine.js','./game.js','./monsters.webp','./manifest.webmanifest','./world.webp','./icons/apple-touch-icon.png','./icons/icon-192.png','./icons/icon-512.png',...['field','battle','ending','capture','victory','heal','evolve','attack','skill','defeat','click','step'].map(x=>'./audio/'+x+'.mp3')];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting()));});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request)));});
